package org.brightstats.model;
import java.util.*;
import com.google.gson.*;
import org.brightstats.model.TypedDiagram.*;
import org.brightstats.model.ElementType.Family;
import org.brightstats.stats.*;

/** RAM compilation: error glyphs bind disturbances; they are not additional observed columns. */
public final class DiagramSem {
    private DiagramSem(){}
    public record Compiled(SemModel.Prepared prepared,List<String> warnings){public Compiled{warnings=List.copyOf(warnings);}}
    private record Estimate(boolean free,double value,String equality,Double lower,Double upper,double scale){}
    private static final class Group {String name;List<SemModel.Location> locations=new ArrayList<>();double start,scale;Double lower,upper;Group(String name,Estimate value){this.name=name;start=value.value;scale=value.scale;lower=value.lower;upper=value.upper;}}
    private static final class Builder {
        final double[][] a,s;final double[] means;final Set<String> occupied=new HashSet<>();final Map<String,Group> groups=new LinkedHashMap<>();
        Builder(int size){a=new double[size][size];s=new double[size][size];means=new double[size];}
        void put(SemModel.Kind kind,int row,int column,Estimate value,String name){int lo=kind==SemModel.Kind.COVARIANCE?Math.min(row,column):row,hi=kind==SemModel.Kind.COVARIANCE?Math.max(row,column):column;String location=kind+":"+lo+":"+hi;if(!occupied.add(location))throw new IllegalArgumentException("Multiple diagram elements define the same RAM entry: "+name);if(kind==SemModel.Kind.DIRECTED)a[row][column]=value.value;else if(kind==SemModel.Kind.COVARIANCE){s[row][column]=value.value;s[column][row]=value.value;}else means[row]=value.value;if(value.free){String label=value.equality.isBlank()?name:value.equality;Group group=groups.computeIfAbsent(label,unused->new Group(label,value));if(value.lower!=null)group.lower=group.lower==null?value.lower:Math.max(group.lower,value.lower);if(value.upper!=null)group.upper=group.upper==null?value.upper:Math.min(group.upper,value.upper);group.locations.add(new SemModel.Location(kind,row,column));}}
        SemModel.Model finish(List<String> names,int[] observed){List<SemModel.Parameter> parameters=new ArrayList<>();for(var group:groups.values())parameters.add(new SemModel.Parameter(group.name,group.locations,group.start,group.scale,group.lower,group.upper));if(parameters.size()>512)throw new IllegalArgumentException("Typed CB-SEM exceeds the 512-free-parameter working limit.");return new SemModel.Model(names,observed,a,s,means,parameters);}
    }
    public static Compiled compile(Document document,List<String> columns,double[][] data,boolean meanStructure){
        if(document.family()!=Family.CBSEM)throw new IllegalArgumentException("Choose a CB-SEM diagram.");if(columns.size()!=Matrices.width(data,3)||new HashSet<>(columns).size()!=columns.size())throw new IllegalArgumentException("Use uniquely named prepared data columns.");List<Node> variables=document.nodes().stream().filter(node->node.type()==ElementType.CBSEM_LATENT_VARIABLE||node.type()==ElementType.CBSEM_STANDARD_MANIFEST_VARIABLE||node.type()==ElementType.GENERIC_MANIFEST_VARIABLE).toList();if(variables.isEmpty()||variables.size()>128)throw new IllegalArgumentException("Define 1–128 RAM variables.");List<String> names=new ArrayList<>();List<Integer> observed=new ArrayList<>(),selected=new ArrayList<>(),factors=new ArrayList<>();Map<String,Integer> indices=new LinkedHashMap<>();Set<Integer> usedColumns=new HashSet<>();
        for(var node:variables){indices.put(node.id(),names.size());if(node.type().observed()){String binding=DiagramModels.string(node.properties(),"column",null);int column=columns.indexOf(binding);if(column<0||!usedColumns.add(column))throw new IllegalArgumentException("Bind each observed RAM node to one distinct dataset column. Use cross-loading connections to share a single observed node.");observed.add(names.size());selected.add(column);names.add(columns.get(column));}else{if(node.label().isBlank())throw new IllegalArgumentException("Name latent RAM variables.");factors.add(names.size());names.add("Factor: "+node.label());}}
        if(observed.isEmpty()||new HashSet<>(names).size()!=names.size())throw new IllegalArgumentException("Use distinct RAM variable names and at least one observed variable.");if((long)data.length*observed.size()>5_000_000)throw new IllegalArgumentException("Typed SEM selected data exceeds five million cells.");Builder builder=new Builder(variables.size());Map<String,Integer> errorOwners=new HashMap<>();Map<Integer,Node> errors=new HashMap<>();
        for(var link:document.links())if(errorBinding(link.type())){Node a=document.node(link.source()),b=document.node(link.target()),error=a.type()==ElementType.CBSEM_ERROR_TERM?a:b,owner=error==a?b:a;if(error.type()!=ElementType.CBSEM_ERROR_TERM||!indices.containsKey(owner.id())||errorOwners.putIfAbsent(error.id(),indices.get(owner.id()))!=null||errors.putIfAbsent(indices.get(owner.id()),error)!=null)throw new IllegalArgumentException("Each error glyph must bind exactly one distinct RAM variable.");if((link.type()==ElementType.CBSEM_CONNECTION_BETWEEN_MV_AND_ERROR_TERM)!=owner.type().observed())throw new IllegalArgumentException("Error binding type disagrees with its owner role.");if(DiagramModels.bool(link.properties(),"free",false)||link.properties().has("value")&&DiagramModels.number(link.properties().get("value"),"error coefficient")!=1)throw new IllegalArgumentException("Error binding coefficients are fixed at one; set its disturbance variance on the error node.");}
        for(var node:document.nodes())if(node.type()==ElementType.CBSEM_ERROR_TERM&&!errorOwners.containsKey(node.id()))throw new IllegalArgumentException("Attach error glyph "+node.label()+" to its RAM variable.");List<String>warnings=new ArrayList<>();Map<Integer,Estimate> variances=new HashMap<>();
        for(int i=0;i<variables.size();i++){Node node=variables.get(i);var properties=node.properties();Node error=errors.get(i);if(error!=null&&error.properties().has("variance")&&properties.has("variance"))throw new IllegalArgumentException("Set a disturbance variance on its error glyph or owner, not both.");JsonElement supplied=error!=null&&error.properties().has("variance")?error.properties().get("variance"):properties.get("variance");int observedPosition=observed.indexOf(i);double defaultVariance=1,mean=0;if(observedPosition>=0){int column=selected.get(observedPosition);for(var row:data)mean+=row[column]/data.length;double ss=0;for(var row:data)ss+=(row[column]-mean)*(row[column]-mean);defaultVariance=Math.max(1e-6,.4*ss/(data.length-1));}Estimate variance=estimate(supplied,defaultVariance,true,true);variances.put(i,variance);builder.put(SemModel.Kind.COVARIANCE,i,i,variance,"Variance: "+names.get(i));if(properties.has("mean")&&!meanStructure)throw new IllegalArgumentException("Enable mean structure before specifying RAM intercepts.");if(meanStructure)builder.put(SemModel.Kind.INTERCEPT,i,0,estimate(properties.get("mean"),observedPosition>=0?mean:0,observedPosition>=0,false),"Intercept: "+names.get(i));}
        Set<Integer> scaled=new HashSet<>();for(var entry:variances.entrySet())if(!entry.getValue().free&&entry.getValue().value>0)scaled.add(entry.getKey());for(var link:document.links())if(directed(link.type())&&indices.containsKey(link.source())&&indices.containsKey(link.target())){Node source=document.node(link.source()),target=document.node(link.target());if(!source.type().observed()&&target.type().observed()){var value=estimate(link.properties(),.7,true,false);if(!value.free&&value.value!=0)scaled.add(indices.get(source.id()));}}
        for(var link:document.links())if(directed(link.type())){Integer source=indices.get(link.source()),target=indices.get(link.target());if(source==null||target==null)throw new IllegalArgumentException("Directed CB-SEM paths must join latent/observed RAM nodes.");Node a=variables.get(source),b=variables.get(target);if(link.type()==ElementType.CBSEM_CONNECTION_BETWEEN_LV_AND_LV&&(a.type().observed()||b.type().observed())||link.type()==ElementType.CBSEM_CONNECTION_BETWEEN_MV_AND_MV&&(!a.type().observed()||!b.type().observed())||link.type()==ElementType.CBSEM_CONNECTION_BETWEEN_LV_AND_MV&&a.type().observed()==b.type().observed())throw new IllegalArgumentException("CB-SEM connection type disagrees with its endpoint roles.");boolean loading=!a.type().observed()&&b.type().observed(),automatic=loading&&!scaled.contains(source)&&DiagramModels.bool(a.properties(),"autoMarker",true)&&!link.properties().has("free")&&!link.properties().has("equality");Estimate value=estimate(link.properties(),automatic?1:loading?.7:.1,!automatic,false);if(automatic){scaled.add(source);warnings.add("Automatic fixed marker: "+names.get(source)+" -> "+names.get(target)+" = 1. Specify free/value settings or disable autoMarker for an alternative metric.");}builder.put(SemModel.Kind.DIRECTED,target,source,value,"Path: "+names.get(source)+" -> "+names.get(target));}
        for(var link:document.links())if(link.type().covariance()){if(covarianceType(document.node(link.source()),document.node(link.target()))!=link.type())throw new IllegalArgumentException("Covariance connection type disagrees with its endpoint roles.");Integer a=indices.get(link.source()),b=indices.get(link.target());if(a==null)a=errorOwners.get(link.source());if(b==null)b=errorOwners.get(link.target());if(a==null||b==null||a.equals(b))throw new IllegalArgumentException("Covariance links need two distinct underlying RAM disturbances/variables.");builder.put(SemModel.Kind.COVARIANCE,a,b,estimate(link.properties(),0,true,false),"Covariance: "+names.get(Math.min(a,b))+" / "+names.get(Math.max(a,b)));}
        if(document.links().stream().anyMatch(link->link.type()==ElementType.CBSEM_CONNECTION_FOR_MODERATION))throw new IllegalArgumentException("Latent moderation requires an explicit supported interaction-indicator/likelihood workflow; it is not a linear RAM edge.");var model=builder.finish(names,observed.stream().mapToInt(Integer::intValue).toArray());warnings.add("Error glyphs represent disturbances of their owners. Error/latent/observed covariance glyphs map to RAM disturbance covariance entries; they are not arbitrary marginal observed covariances. Identification and positive-definite fitted covariance remain estimator checks.");return new Compiled(new SemModel.Prepared(model,selected.stream().mapToInt(Integer::intValue).toArray(),factors.stream().mapToInt(Integer::intValue).toArray()),warnings);
    }
    private static ElementType covarianceType(Node a,Node b){int x=a.type()==ElementType.CBSEM_ERROR_TERM?2:a.type().observed()?1:0,y=b.type()==ElementType.CBSEM_ERROR_TERM?2:b.type().observed()?1:0;int lo=Math.min(x,y),hi=Math.max(x,y);if(lo==0&&hi==0)return ElementType.CBSEM_CORRELATION_CONNECTION_BETWEEN_LV_AND_LV;if(lo==0&&hi==1)return ElementType.CBSEM_CORRELATION_CONNECTION_BETWEEN_LV_AND_MV;if(lo==1&&hi==1)return ElementType.CBSEM_CORRELATION_CONNECTION_BETWEEN_MV_AND_MV;if(lo==0&&hi==2)return ElementType.CBSEM_CORRELATION_CONNECTION_BETWEEN_ERROR_TERM_AND_LV;if(lo==1&&hi==2)return ElementType.CBSEM_CORRELATION_CONNECTION_BETWEEN_ERROR_TERM_AND_MV;return ElementType.CBSEM_CORRELATION_CONNECTION_BETWEEN_ERROR_TERM_AND_ERROR_TERM;}
    private static boolean directed(ElementType type){return type==ElementType.CBSEM_CONNECTION_BETWEEN_LV_AND_LV||type==ElementType.CBSEM_CONNECTION_BETWEEN_LV_AND_MV||type==ElementType.CBSEM_CONNECTION_BETWEEN_MV_AND_MV;}
    private static boolean errorBinding(ElementType type){return type==ElementType.CBSEM_CONNECTION_BETWEEN_MV_AND_ERROR_TERM||type==ElementType.CBSEM_CONNECTION_BETWEEN_LV_AND_ERROR_TERM;}
    private static Estimate estimate(JsonElement supplied,double defaultValue,boolean defaultFree,boolean variance){JsonObject object=supplied==null?new JsonObject():supplied.getAsJsonObject();boolean free=DiagramModels.bool(object,"free",defaultFree);double value=object.has("value")?DiagramModels.number(object.get("value"),"parameter value"):defaultValue;String equality=DiagramModels.string(object,"equality","");Double lower=null;if(object.has("lower")){if(!object.get("lower").isJsonNull())lower=DiagramModels.number(object.get("lower"),"lower bound");}else if(variance&&free)lower=1e-8;Double upper=object.has("upper")&&!object.get("upper").isJsonNull()?Double.valueOf(DiagramModels.number(object.get("upper"),"upper bound")):null;double scale=object.has("scale")?DiagramModels.number(object.get("scale"),"parameter scale"):Math.max(1,Math.abs(value));if(scale<=0||variance&&value<0||!free&&!equality.isBlank()||lower!=null&&value<lower||upper!=null&&value>upper||lower!=null&&upper!=null&&lower>=upper)throw new IllegalArgumentException("Invalid diagram parameter value, scale, equality label or bounds.");return new Estimate(free,value,equality,lower,upper,scale);}
}
